export const flashcards: Record<string, [string, string][]> = {
  s1: [["Two flop buckets?","1) T-high+ → c-bet 100%. 2) 9-high & below → ~70/30 bet/check."],["Clean T-high+, what %?","100% — every hand. Small size (~25–40%)."],["Why does UTG c-bet so much?","Overpair asymmetry: UTG's linear RFI has far more strong pairs."],["Shorter or deeper → bet more?","Shorter. Overpair asymmetry amplified shallow. Most do the opposite."],["Primary risk factor?","Straights possible. 1 → still bet. 3 → slow down heavily."],["Secondary risk factors?","Ace-monotone · AK2/3/4 · deeper stacks · high-low-low (paired low under high)."],["KK3 rainbow a risk factor?","No. High-high-low is fine → c-bet 100%. Only paired low under high (K33) counts."],["On risk board, which CHECK?","Medium-strength: underpairs, medium aces, AK/AT/KQ."],["On risk board, which BET?","Very strong (sets, flushes, 2pair) AND very weak (trash)."],["A95 monotone — QJo no-heart?","Bet. It's trash. QJo with heart (draw) → check."],["Bucket 2 default?","~70/30. Strong+weak bet, medium checks. Can't go 100%."],["Default c-bet size?","1/4 to 1/3 pot (~25–40%)."]],
  s2: [["Three flop buckets?","1) Ace-high → 100%. 2) T–K high + deuce/3 → 100%. 3) 9-high & below → 60/40."],["Ace-high risk factors?","Stack depth (deeper→check), monotone, paired."],["T–K + deuce/3 risk factors?","Two low cards (biggest), monotone. Paired less concerning."],["When BTN misses low boards?","Bet top, bet bottom (selective), check middle. Can't bet all bluffs."],["Two-suit awareness?","BB calls with TWO suits. Block the non-flush-draw suit too (no equity risk)."],["K83 two-tone, KJ with which suits?","Heart+diamond (both on-board) = pure bet. Spades+clubs (both off) = pure check."],["AJJ strategy?","Paired ace-high → not 100%. Check KK/QQ/medium. Bet Jx + trash."],["K92 strategy?","K-high + deuce → c-bet 100%. 86–90% solver; simplify to 100%."]],
  s3: [["Fold target vs SB stab?","~25% (1bb into ~3.7bb). Defend ~75%. Focus on the 25% you fold."],["Which cards NOT relevant?","Ace and deuce. Everything has over/under. Ignore them."],["Three defending mechanisms?","1) High-card defending. 2) Three to a straight. 3) Backdoor flush draw."],["Double overs / over-under / double unders?","Double overs = easy play. Over-under = sensitive. Double unders = fold unless gut shots."],["BDFD always enough?","No. Worst hands (42s on K77) still fold even with BDFD. Identify worst first."],["Key card height heuristic?","High key card (8) → rarely fold double-overs. Low key card (5) → fold more."],["Paired board — which card?","The unpaired high card. Can't have equity vs trips."],["Preflop asymmetry BvB?","SB has folding range; BB doesn't. 2x/3x favor BB. BB capped (no AK/AQ/overpairs)."]],
  s4: [["Two-system approach?","System 1: bottom of range up (weakest first, prioritize LOW card). System 2: blocking effects. Prioritize System 1."],["Why prioritize low card?","Low cards have good blocking effects vs linear ranges. Low EV when checking."],["When is System 2 easy?","Board 3-flushes → one-club bias (blocks flushes + hero calls)."],["When is System 1 forced?","Wide ranges (no obvious suit), or three Broadway + EP (no offsuit air)."],["Busted straight + flush draw?","Terrible bluff — blocks both folding regions. Prefer one or the other."],["High vs low card of suit?","High card (K♥) worse to hold when bluffing (blocks more folds). Low card less damaging."],["Value bets require bluffs?","Yes (in common scenarios). Bluffs need value to carry them."],["The realism constraint?","Can't always have ideal bluff (hearts bet flop/turn → no hearts left). Bluff with what you have."]],
  s5: [["Core mistake?","Barreling medium-strength hands that should check. Lose to calls above, only beat bluffs."],["The pyramid?","Bet top (nuts) + bet bottom (trash, selective) + check middle (medium)."],["Deep vs short?","Deep → opponent calls more top pair (more callers above). Short → CRs top pair (fewer calls above)."],["When can medium hand bet?","Merge play: strong enough to fold better AND called by worse (ATo on Q73→J)."],["Default turn sizing?","Polarize — pot-ish or check. Avoid medium sizing with medium hands."],["J9 on Q73→J?","Check — J9 no kicker is medium. AJ with A♦ minimum to barrel."],["99 on K72→Q?","Check — medium, opponent has many K-x calls. 88 (open-ender) borderline."]],
  s6: [["Stack inflection for CR top pair?","35bb. Above → nuts-oriented. At/below → aggressive top-pair CR. Shorter = more CR."],["Top pair vs two pair/sets?","Top pair = CR. Two pair/sets = trap (check-call). SPR short enough to shove river."],["CR hierarchy on Q73?","KQ/QJ/QT pure CR. Q9 heavy. Q8 medium. Q7-Q4 taper. Q2 pure call."],["Backdoor FD effect?","Prefers check-call (Q9♥ calls more than Q9o). Realize the flush draw."],["Low vs high boards for CR?","Low: kicker matters less, draw factors more. More chaotic."],["Two low cards touching (Q75)?","3-straight top pairs (Q5,Q6,Q2) may CR MORE than non-straight (Q7,Q8)."],["Opponent c-betting 100%?","CR all top pairs — their range too weak to defend."],["CR sizing?","Small (~3x the c-bet). Short stacks = 2-street game."]],
  s7: [["MDF formula?","Fold% = Risk / (Pot + Risk). But villain bluffs have real equity → actual fold% is LOWER."],["How much defend vs CR?","Most of range (65–80%+). Focus on the small folding range."],["Organize around which card?","Highest unpaired card. Two overs = pure call. Double unders = fold candidates."],["Defend priority for trash?","1) Direct equity (A-high). 2) BDFD (high card). 3) 3-straight. 4) BD straight. 5) Blockers."],["Paired board (K55)?","Organize around unpaired card. Ace + BDFD = pure call."],["Blocker suits on two-tone?","Avoid suit villain bluffs with — blocks their bluff frequency."],["Naked BDFD (no straight, no high)?","Worst defendable — may fold (T9 with only BDFD)."],["HUD exploit risk?","If fold-to-CR too high, regulars exploit you."]],
  s8: [["IP sizing default?","Bet LARGER on average. IP can polarize (check uncaps on next card)."],["Villain capped (low nut ratio)?","Overbet / pot (geometric to get stacks in)."],["Villain has nuts possible?","~70% pot — large but not overbet."],["< 50% pot IP?","Almost NEVER correct. Risk of CR not worth the small reward."],["Geometric betting?","~pot on both streets to get stacks in (equal fractions)."],["Turn check-back inflection?","If you checked turn, villain's river check = weakness → bet big, not small."],["Quads risk?","~48 combos (similar to ~45 flush on 3-flush). Don't assume villain can't have quads."],["Merge bet?","Pot with medium-strong (Queens) folds better + called by worse."]],
  s9: [["Three inputs for wide defending?","Weak own range + Weak opponent range + Small bet = defend very wide."],["Bottom pair + BDFD?","Call. BDFD > good kicker almost always."],["Super gut shot (gut + BDFD)?","Call — turns combo draws on suit cards."],["Naked gut shot (double unders)?","Fold — no direct equity vs value range."],["CR criteria (properties)?","Direct equity, BD straight, BD flush, opponent missed, small bet, high card of suit."],["Bet sizing sensitivity?","Scale up → fold more pairs. Q-J without ♦: call vs 30% → fold vs 83%."],["Rainbow vs two-tone?","Rainbow = messier (fewer BDFDs). Two-tone = cleaner (flush draws supplement)."],["Blind vs blind?","Ranges too wide — never fold pairs (even pocket 4s with BDFD)."]],
  s10: [["Central thesis?","Absolute strength irrelevant. Relative strength (vs opponent's range) determines value."],["Inflection points weakening villain?","Checks turn/river, no raising, small bets → subtract strong hands."],["Can't CR but called by worse?","Bet. Don't let opponent polarize by checking."],["Opponent checked turn, medium hand?","Block bet small (25–33%) — forces them to defend 75%+."],["Opponent capped?","Bet large / overbet. Large vs capped ranges."],["Short SPR (<2x pot)?","Prefer jamming. Checking loses optionality."],["What does checking do?","Converts strong hands to bluff catchers. IP auto-polarizes (bets better, checks worse)."],["Multi-way IP checked flop?","Extremely capped (no sets, no TPTK). Largely ignore them."]],
  s11: [["Three keys to hero calling?","1) Range awareness. 2) Unblock bluffs. 3) Block value."],["When to focus on which key?","Wide value range → unblock bluffs (#2). Narrow → block value (#3)."],["Good vs bad bluff catcher?","Good: blocks value (King), unblocks bluffs (4,3,2). Bad: blocks bluffs (8,9,T)."],["Why does 4-x unblock bluffs?","BTN opens suited 5+ and offsuit 8+. 4-x wasn't opened → doesn't block bluffs."],["Opponent's required bluff frequency?","= your pot odds. Need 25% → they must bluff 25% of betting range."],["No natural bluffs?","Fold even if MDF says call. No draws missed, opponent won't bluff Ax."],["CR opportunity?","If opponent bets too small IP, CR second pair can fold better + call worse."],["Toy game lesson?","Not all bluff catchers equal. 87s (blocks 77, unblocks JTs) worth ~27% pot; 88 worth 0."]],
  s12: [["Two board buckets?","T-high+ → tight (fold 50%+). 9-high & below → resilient (~25%)."],["A-high or K-high?","Extreme caution. Highest fold %. Most over-defended."],["Why fold on high boards?","3-bettor ahead preflop. High boards favor them. Fold far more than MDF."],["Why defend on low boards?","Low boards favor caller (3-bettor misses). Defend near MDF."],["Low board risk factors?","Paired (minor), disconnected (significant — want straights), deuce present (favors 3-bettor)."],["Mistake on A/K-high?","Over-defending weak pairs (77/88/99) and BDFDs — all folds."],["Mistake on low boards?","Over-folding high card hands. K-J with BDFD, A-T 3-straight are calls."],["vs jam on low disconnected?","Often a call — neither range hits."]],
  // ---- Bubble Mastery ----
  bmprimer: [["ChipEV vs ICM fundamental?","Chips scale linearly ($2=$2). ICM: doubling your stack less than doubles your equity."],["Three ICM pitfalls?","No skill edge, no future hands, no incoming blinds/position. Breaks down at large fields."],["What does FGS add?","Future Game Simulation — simulates N future hands, capturing blind cycles and forced all-ins."],["Why no FGS multi-table?","Computational complexity — game tree compounds exponentially per future hand."],["4.5bb UTG, posts BB next — ICM vs FGS?","FGS wider (~25% vs 18%). Fold equity now beats paying BB+ante (~112bb/100)."],["1.5bb UTG, forced all-in next — ICM vs FGS?","FGS tighter (~25% vs 49%). No fold equity; doubling doesn't help; fold and let others bust."],["15bb HJ, shorter stack present — shove or min-raise?","Min-raise only. Open shoving JTs loses ~$35 in tournament equity. FGS eliminates shoves."],["Which hands gain value in ICM opens vs ChipEV?","Ace-X blockers (A2s, A9o). Opponents 3-bet/fold, not cold call — blocking matters more than playability."],["How does cold calling change as stacks shorten under ICM?","Fades aggressively — calling 2bb off 20bb risks too large a % of stack near the bubble."],["3-bet bluff range: ChipEV vs ICM?","ChipEV: board-coverage (suited connectors). ICM: blocker-heavy (Ace-X suited, King-X suited)."],["3-bet value threshold under ICM?","Tightens — Queens often flat, AKo barely 3-bets, Kings+ default."],["1000-player vs 200-player bubble — which more extreme?","1000-player (2/152 = 1.3% bust) is more extreme than 200-player (3/33 = 9.1%). Use 1000 for direct-bubble study."]],
  bm1: [["Why do blockers beat playability in ICM opens?","Opponents 3-bet/fold, not cold call. A2s blocks their 3-bet bluffs; 76s has no blocking value."],["Cold calling stronger = less capped?","Calling AQo/AJs/KQ means high-card board coverage — opponent can't barrel you off easily."],["Smaller 3-bet in ICM, yet defense tighter?","ICM 3-bet ~7.35bb vs 8.6bb ChipEV, but defender plays narrower. Risk premium overwhelms price."],["FGS can make you open tighter when short?","Yes — 1.5bb UTG: ICM says 49%, FGS says 25%. Folding has value when others bust for you."],["Open shoving 15bb on bubble with shorter stack?","Massive leak. Min-raise is 4-5x better in equity. AJo: +$1 min-raise vs -$17.70 shove."],["Zero-EV opens — open or fold?","If opponents overfold: open (positive). If Nash: fold. Decided by FGS + tendencies."],["Field size impact?","2/152 (1000-player) = more extreme than 3/33 (200-player). Use 1000-player model for direct bubble."],["Shove wider or tighter when short with fold equity?","Wider — 4.5bb FGS widens to 25%. Cost of posting blind next hand justifies shoving now."],["Shove wider or tighter when forced all-in next?","Tighter — 1.5bb FGS tightens to 25%. No fold equity; doubling leaves you in same spot."],["What hands drop from opens in ICM?","Low pairs, weak suited connectors, offsuit broadways — speculative play loses value."],["Value threshold tightens how?","AK barely 3-bets, Queens often flat. Kings+ becomes the default 3-bet value range."],["BTN open sizing ICM vs ChipEV?","2.1x (ICM) vs 2.3x (ChipEV). Smaller open, yet defense still tighter."]],
  bm2: [["Covering table from EP — how much wider?","Roughly 2x+ baseline. UTG ~16.5% baseline → ~35% when covering."],["What dictates shove vs min-raise when covering on BTN?","BB depth. Heavy open shoves appear when blinds sub-20-25bb; min-raise when 30bb+."],["Covered by one but cover the rest — tighten?","No. Still wider than baseline. Covering player folds ~80%; you pressure stacks you cover."],["BB very short (sub-5bb) — open range composition?","High-card dense, Ax-heavy. Drop suited connectors and low pairs — want raw equity."],["BB deep (40-68bb) — open range composition?","Low suited connectors, low pairs, suited high-low all acceptable — want playability."],["Covered at 12bb BTN vs BB 53bb — how wide?","~20%. Almost no open shoves. Offsuit Ax very poor. Common leak: autopilot shoving."],["Covered at 12bb BTN vs BB 16bb — how wide?","~28% (wider). Closer stacks = game of chicken; BB risks tournament life playing back."],["Why fold low pairs (22-33) when covered and short?","They block the blinds' pair-folds — bad when you rely on fold equity."],["UTG covered by most at 29bb — how tight?","~9%. Folds nines, AJo, KQo, A9s in some configs."],["Common leak at 30-40bb covered on BTN?","Over-tightening. Still ~35%. BB must risk heavily to pressure you."],["Covering and called — disaster?","No. You still cover. Losing the pot doesn't end your tournament; you retain equity."],["FGS effect when short stacks at other tables?","Tighten further — folding has positive $EV when others may bust before you."]],
  bm3: [["Covering table from EP — how much wider?","Roughly 2x+ baseline. UTG ~16.5% → ~35% when covering."],["Heavy open shoves when covering — when?","When blinds are sub-20-25bb. Commonly missed by regs — a major leak."],["Covered by one, cover rest of table — still wide?","Yes. ~80% the covering player folds; you pressure the stacks you cover."],["Same 12bb BTN stack — BB 53bb vs BB 16bb?","20% vs 28%. BB's depth, not just yours, drives your range."],["Covered 12bb BTN — open shove hand shift?","Stronger. AQ not AJ. Offsuit Ax shove terribly. Drop A2s/A3s."],["Covered by massive stack on BTN — cap?","No wider than ~35%. Trim thinnest suited/high-low and lowest pairs."],["Very short BB (sub-5bb) — composition?","High-card dense, Ax-heavy. Drop speculative hands for raw equity."],["Low pairs when covered and short — open or fold?","Often fold. They block blind pair-folds, hurting fold equity."],["Deeper (30-40bb) covered — how tight?","Don't over-tighten. ~35%. BB must risk a lot to pressure you."],["Limping threshold SB covered?","~18bb effective. Below that, no limps — pure shove/fold."],["BB fold freq when SB covers (short)?","~78-90% (vs ~37% chip model). Limping gives free equity — shove/raise."],["Open-shove hand shift in ICM when covered?","Shift up. Drop A2s/A3s; AJo becomes threshold. Bluffs shift up too."]],
  bm4: [["SB covers short BB on bubble — limp or shove?","Shove/raise, no limps. BB overfolds ~85%; limping gives free equity."],["Limping reappears for covered SB at?","~18bb effective. Below: pure shove/fold."],["Open-shove selection covered in ICM?","Shift up — drop A2s/A3s, shove AJo+ threshold, mid pairs over low pairs."],["Close stacks BvB (14 vs 16bb)?","Wider VPID. Game of chicken — BB can't defend wide (losing hurts them)."],["40+bb covered SB — limp-shove?","Disappears. Limp-call pairs; BB can't pile vs uncapped trapping range."],["BB fold freq vs SB cover (short)?","~78-90% (vs ~37% chip model)."],["Covering SB at 22bb — shove or limp?","Depends on other-table ICM pressure. More pressure = more shoving."],["Covered deep (37+bb) — BB ISO?","~49.5% (vs 42% chips). SB overfolds to ISO; limp-shoves less."]],
  bm5: [["SB cold-call threshold facing open?","~20bb. Below: ~0% cold calls, raise/fold only."],["SB cold calls wider when BB is short — why?","BB handcuffed (can't squeeze/lead). SB 'almost in the BB' — realizes more equity."],["Covered by wide opener — re-steal or call?","Re-steal. Win outright more often AND avoid losing postflop ~50%+ of time."],["3-bet sizing in high ICM from blinds?","Size up — deny equity to speculative calls, lower SPR for narrow value."],["3-bet value threshold covered vs EP?","Kings+, AQ (Queens mix). Much narrower than chip model."],["BB covers opener and SB — SB cold calls?","Shrinks. BB can squeeze/lead post. SB plays closer to raise/fold."],["BB defends wider vs tight UTG open when covering — why?","Can donk-lead low/mid boards that miss UTG's tight range. More equity realization."],["First hands trimmed from BB ICM defense?","Dominated offsuit gappers/connectors, weakest suited, weakest Ax offsuit."]],
  bm6: [["Cold call vs 3-bet — what determines it?","Your stack relationship to the 3-bettor. Cover them (50v25) = call; covered (25v50) = raise/fold."],["How does BB stack affect UTG open width?","UTG opens wider when BB short/covered; tighter when BB has big covering stack."],["SB cold call vs UTG when BB very short (10bb)?","Narrow value range — protected. UTG's tight range + short BB = can't squeeze."],["Raise to 7.9bb leaving 0.1 behind?","Leak. Raise to ~5bb to fold to jam+call behind (caller shows QQ+). Or shove."],["Zero-EV fringe hands on bubble?","Let FGS + tendencies decide. Short stack elsewhere = lean fold."],["3-bet sizing by depth?","~6-6.5bb mid; ~8-8.5bb at 45+bb. Matching range to size matters more than number."],["UTG+1 3-bet vs UTG deep (50bb)?","Jax+, AQ. Tens ~0 EV. Very thin bluffs only."],["Over-exploiting on bubble?","Doubly costly — stolen equity spreads to ALL players, not just exploiter."]],
  bm7: [["Quick ICM pressure gauge?","Players to bust ÷ total players left, as % of field."],["1 to bust out of 8 vs 1 of 16 — which tighter?","1/8 = 12.5% → tighter. 1/16 = 6.25% → looser. Absolute number meaningless without %."],["Short stack other table, posting BB next, you cover?","Tighter opens. Nearly locked to cash — risk premium spikes."],["Short-stack vs chip-leader range precision?","1-2% error costs short stack 10-20% of stack; chip leader 1-2%. Study short ranges."],["What can't multi-table ICM sim capture?","Other-table stack positions, who posts next, blind increases, someone already busting."],["Player busts on other table, you cover them?","Drop high-ICM ranges immediately — you're now ITM."]],
  bm8: [["Covered BB on bubble — donk lead freq?","Almost never. BTN's wider range connects better; BB's tight range connects worse."],["BB check-raise sizing on low boards?","All-in (check-shove). Small raises let IP draw out — catastrophic under ICM."],["Top pair on A-K-x / A-Q-x as covered BB?","Pure check-call. ~88-90% equity, board lockdown — no protection needed."],["Top pair on Q-high — check-raise?","Yes if ≥83-85% equity. K/A turn can outdraw; ace-high can't."],["A-A-8 vs A-8-8 — which gets check-raise range?","A-8-8 (high-low-low). BB has the pair. A-A-8 (high-high-low): pure check-call, no pair."],["Turn FD on board — check-call or raise?","Call if you unblock IP's bluffs; raise if you block them (more likely vs value you beat)."],["Adding click-raise for IP does what?","Drops BB check-raise sharply. Non-all-in check-raises 'really suck in ICM'."],["BTN covers BB — default c-bet strategy?","Range bet. BB check-raises far less; BTN has more board coverage. Risk factors neutralized."],["Two reasons BTN range-bets more when covering?","1) BB rarely check-raises. 2) BTN ~70% vs BB ~20-30% defense — ranges nearly flipped."],["Which monotone boards need check-back?","Those connecting OOP: A-K-8♣, A-9-8♣, K-J-3♣, K-9-8♣, Q-8-3♣, J-10-8♣."],["K-K-9 vs K-K-4 — which checks back?","K-K-9 (9 connects BB). K-K-4 ~95% range bet."],["When is 'always range-bet' approximately correct?","When you cover BB by more than ~2x their stack."]],
  bm9: [["Biggest postflop shift when BB covers BTN?","BB donk-leads low/paired boards near-range — doesn't exist in chip-EV or when BTN covers."],["Stack ratio threshold for BB leads?","Covering BTN by ~1.5-2x+ their stack."],["5-5-4 covering vs covered?","Near-range lead when covering; no leads when covered (BB lacks 5x)."],["J-J-2 covering — flop strategy?","Heavy check-raise, minimal check-call. Near check-raise-or-fold."],["River raise sizing when covered?","Non-all-in. Leave equity behind for times called and lose. Never jam when avoidable."],["9-6-3 rainbow, covered BTN with tens — sizing?","Jam ~118% pot for protection. Bet-calling lets BB CR draws and stack you."],["BTN still range-bets which boards when covered?","Ace-Broadway-Broadway: A-K-Q, A-K-J, A-K-T, A-Q-T, A-J-T."],["A-Q-2 rainbow covered — sizing?","Polar ~105% overbet + check (no small bet). Folds out gutters (5-4, 4-3)."],["What kills the front-load overbet?","Open-ended straight draws (can't fold out) and flush draws (don't want bet-call stacks-in)."],["Monotone covered — c-bet freq?","~50% check. Range bet when covering; passive when covered."],["BB under-leads low boards — exploit?","BTN checks back range (pure). No betting range needed."],["Blocker suit on river calls?","Matters enormously with narrow ranges. Call flush suit, fold off-suit (~17bb EV swing)."]],
  bm10: [["Check-shove vs UTG — profitable?","No. UTG folds only ~60%; need >75%. UTG's range too strong (sets, overpairs, TPTK)."],["River polar sizing on bubble?","~13.5bb leaving 1-3bb behind. Never shove. 1-3bb worth ~$200 in $100 tourney."],["K84 short stack ICM — check-raise threshold?","KQ only. KJ/KT/K9 and below = pure check-call. ICM threshold much stronger."],["Short vs deep BB — flush % in range?","Short: 17.8% (tight range suited-heavy). Deep: 12.5%. Short leads more on flush turns."],["A♠ vs 4♠ turn — which better for BB?","A♠ (removes IP's suited aces). BB leads 40% on A♠, 26% on 4♠."],["AJ vs AT river after ace pairs — strategy?","AJ checks (blocks KJ bluff-catcher). AT value-bets (doesn't block KJ)."],["UTG covers BB by 2x+ — c-bet freq?","~90%+. Range bet almost all boards. BB's tight defense lacks coverage."],["Stacks close (66v58bb) — c-bet freq?","~50% on mid connected. Game of chicken. Stack gap > coverage fact."],["854/752/A44 vs short BB — bet or check?","Range bet. BB's tight ICM range folds offsuit connectors — can't connect. (Check in chip.)"],["AK7 vs 40bb+ BB — strategy?","Big-bet/check split. Check QQ/JJ/TT/weak Ax; bet large (67-80%) with strong hands."]],
  bm11: [["Default c-bet freq on monotone, 12bb polar?","Range check (65-82%+). BTN lacks flushes — open-shoves suited pre."],["BTN range vs 53bb BB vs 16bb BB?","Tighter (every tier shifts up). But BB defends wider (less ICM risk for deep stack)."],["Sizing on two-tone vs rainbow?","Two-tone adds flop jam (~2x pot) to deny FD equity and stop check-shoves."],["A77 vs A99 — which checks more?","A99 — higher paired card = more BB 9x combos (J9, T9). More coverage = more checking."],["Standard vs dry ace-high c-bet size?","Quarter pot (~25%) standard; ~40% on dry ace-high (AQ4) to deny gutshots."],["J-5-4 dry vs 53bb BB — bet or check?","Range bet. Tighter range = more top pair/overpair, less air."],["6-6-2 rainbow vs 6-6-5 — strategy?","6-6-2: range bet (BB underrepresented, no draws). 6-6-5: check ~40% (draws flip it)."],["J-10-7 two-tone — which overpair jams most?","Queens jam most, Kings less, Aces pure check. Nut traps; weaker protects."],["BB under-leads monotone (<20%) — exploit?","Check back range. No betting range needed."],["Worst Axo shove vs 53bb BB?","A8o (vs A4o at 16bb). Value-jam threshold moves up as covering stack deepens."],["BB small-3-bet AJ offsuit in high ICM — why?","BTN can't cold-call wide; small 3-bet folds more of BTN's range."],["Q10 — the universal flop shove?","Yes. Q10 jams across many textures at 10-12bb post polar open. One combo to remember."]],
};

export const quizzes: Record<string, QuizQuestion[]> = {
  s1: [{q:"T-high+ disconnected, no straights. UTG RFI, BB checks. Best line?",o:["C-bet 100%","Check medium, bet rest","Check everything","C-bet only strong pairs"],a:0,why:"Clean T-high+ → 100% c-bet, every hand. No risk factor."},{q:"K♥K♦3♣ (high-high-low). Strategy?",o:["Slow down","C-bet 100%","Check 50%","Check medium"],a:1,why:"High-HIGH-low is NOT a risk factor. Only paired low under high. Bet 100%."},{q:"A♥9♥5♥ (ace-monotone). QJo no heart. Action?",o:["Check — risk board","Bet — it's trash","Check-raise","Fold pre"],a:1,why:"Risk factor (slow down), but QJo no-heart is trash → bets. Only medium hands check."},{q:"J♣6♦6♠ (high-low-low). How often does solver check?",o:["~0%","~50%","~100%","Never — bet 100%"],a:1,why:"High-low-low with paired low → ~50% checks."},{q:"Stacks 20bb. Clean T-high+ board. You should...",o:["C-bet less","C-bet more — overpair asymmetry amplified","Never c-bet","Check-raise"],a:1,why:"Shallow amplifies overpair advantage → bet MORE. 'Bet less when short' is a leak."},{q:"T55 rainbow. T-high+ AND high-low-low. What applies?",o:["T-high+ wins → bet 100%","High-low-low wins → mix","Both → check all","Neither"],a:1,why:"Paired-low risk factor overrides T-high+. Mix: bet A5s/5x/TT/JJ, check 99–66/AK/AQ."}],
  s2: [{q:"Three flop buckets for BTN vs BB?",o:["Ace-high → 100%; T–K+deuce/3 → 100%; 9-high & below → 60/40","Same as System 1","Only two buckets","All 100%"],a:0,why:"BTN has three buckets. Ace-high and T–K with deuce/3 get 100%; 9-high and below get 60/40."},{q:"AJJ (paired ace-high). Strategy?",o:["C-bet 100%","Not 100% — check KK/QQ/medium, bet Jx + trash","Check everything","Bet only Jx"],a:1,why:"Paired ace-high is a risk factor. Bet strong + weak; check medium."},{q:"K63 (K-high + deuce, but two low cards). Strategy?",o:["100% — deuce present","Not 100% — second low card causes problems","Check everything","Bet only sets"],a:1,why:"Two low cards is the biggest risk factor for T–K high. K92 is fine; K63 is not."},{q:"543 two-tone. BTN misses (no 8+). Ace-high is...",o:["A bluff (bet)","Medium strength (check)","Strong (value bet)","Fold"],a:1,why:"Ace-high beats trash but loses to all pairs → medium → check. Bet strong + weak."},{q:"K83 two-tone, KJ with spades+clubs (both off). Action?",o:["Bet — backdoor potential","Pure check — blocks nothing useful","Check-raise","Fold"],a:1,why:"Both off-board suits = pure check. KJ with heart+diamond (both on-board) = pure bet."},{q:"BTN vs BB, 25bb, AKQ flop. Strategy?",o:["Check — straights possible","C-bet 100% — shallow stack","Check-raise","Fold pre"],a:1,why:"Shallow stack on ace-high → bet 100%. Stack depth is key; shallow = more betting."}],
  s3: [{q:"Fold target vs SB limp stab?",o:["~50%","~25% (1 into ~3.7)","~10%","~75%"],a:1,why:"1bb into ~3.7bb pot. 1/4 = 25%. Defend ~75%."},{q:"Which cards are NOT strategically relevant?",o:["King and 5","Ace and deuce","Ace and king","Deuce and 3"],a:1,why:"Everything has overcards to deuce / undercards to ace. No over-unders to either."},{q:"K77 paired. Which card do you build around?",o:["The 7 (paired)","The king (unpaired)","Both","Neither"],a:1,why:"Can't have equity vs trips. Evaluate around unpaired high card."},{q:"A42 two-tone. Worst hands contain which card?",o:["A 3","A 7","A deuce","A 5"],a:1,why:"3x and 5x have gutshots. 6x has backdoor straights. 7 is most disconnected."},{q:"K62 two-tone. 73 with spade. Action?",o:["Play — BDFD","Fold — worst hand, BDFD not enough","Check-raise","Call — gutshot"],a:1,why:"73 is worst hand (over-under to 6). Even with BDFD, it folds. 75 (3-straight) pure."},{q:"Key card: low (5) vs high (8). Double-overs?",o:["Same — always play","Low: fold more (plenty below). High: rarely fold (rare).","Always fold","Always play"],a:1,why:"Low key card = more double-unders below → double-overs less valuable."}],
  s4: [{q:"System 1 for river bluffs?",o:["Bluff strongest first","Bluff from bottom up (weakest first, prioritize LOW card)","Bluff middle","Best blockers only"],a:1,why:"Weakest hands have lowest EV when checking → lowest opportunity cost."},{q:"Board 3-flushes on river. Which system is easy?",o:["System 1","System 2 (one-club bias)","Neither","Both equally"],a:1,why:"One club blocks flushes AND hero calls. Obvious blocking effect."},{q:"Three Broadway, EP open. Why is System 1 forced?",o:["No offsuit air exists (linear range)","System 2 is wrong","Solvers don't work","Too deep"],a:0,why:"Linear EP range has no offsuit air. Only suited hands can bluff — scarce."},{q:"QJ♥ on river (busted straight + flush). Good bluff?",o:["Yes — double draw","No — blocks both folding regions","Only if shallow","Only vs passive"],a:1,why:"Blocking both busted straight AND flush draws is terrible."},{q:"Hearts bet flop+turn. On river, bluff with heart?",o:["Yes — hearts best","Rarely — you lost them on earlier streets","Always","Never"],a:1,why:"Realism constraint: if hearts bet earlier, you won't have them on river. Bluff with what you have."}],
  s5: [{q:"Core mistake in barreling?",o:["Betting too small","Barreling medium-strength hands that should check","Not bluffing enough","Betting too large"],a:1,why:"Medium hands lose to calls above, only beat bluffs. Check them as bluff catchers."},{q:"99 on K72→Q turn. Action?",o:["Barrel — overpair","Check — medium, opponent has many K-x calls","Check-raise","Fold"],a:1,why:"Pocket 9s is medium. Opponent has many K-x calls above you. 88 (open-ender) borderline."},{q:"ATo on Q73→J. Merge — bet or check?",o:["Check — medium","Bet — folds Q-x/K-x, called by worse","Fold","Check-raise"],a:1,why:"ATo folds better (Q-x, K-x) AND called by worse (J-T, draws). Classic merge."},{q:"Default turn sizing?",o:["30% pot","Pot-ish or check (avoid medium with medium hands)","Min-bet","Overbet only"],a:1,why:"Polarize: bet big (pot, ~116% overbet) or check. Medium doesn't rescue medium."},{q:"Deep stacks (80bb+) effect on medium hands?",o:["More barrelable","Opponent calls more top pair → more callers above","Less betting","No effect"],a:1,why:"Deep = opponent calls more top pair. Medium hands face more callers above."}],
  s6: [{q:"Stack-depth inflection for CR top pair?",o:["50bb","35bb","20bb","100bb"],a:1,why:"Above 35bb → nuts-oriented. At/below → aggressive top-pair CR. Shorter = more CR."},{q:"Top pair vs two pair at short (25bb)?",o:["Both CR","Top pair = CR; two pair/sets = trap (check-call)","Both check-call","Both fold"],a:1,why:"SPR short enough to shove river without raising. Top pair CR; two pair/sets trap."},{q:"Q73, Q9 offsuit vs Q9♥ (backdoor FD)?",o:["Both CR equally","Q9o CR; Q9♥ check-call (realize flush draw)","Both check-call","Q9♥ CR more"],a:1,why:"Backdoor FD prefers check-call to realize the draw. Offsuit CRs."},{q:"K84, 13bb, K7o. Action?",o:["Check-call — too strong to fold","Check-raise — too short to call","Fold","CR only with KQ"],a:1,why:"13bb = too short to call. KQ pure CR; K7–K2 pure CR (offsuit). BDFD → check-call."},{q:"Low boards vs high boards for CR?",o:["Same — kicker determines everything","Low: kicker less, draw factors more. More chaotic.","Low: always CR","High: always check"],a:1,why:"Opponent can't make top pair with low suited connectors. Secondary factors dominate."}],
  s7: [{q:"MDF formula for fold %?",o:["Pot / Risk","Risk / (Pot + Risk)","Risk / Pot","Pot / (Pot + Risk)"],a:1,why:"Makes zero-equity bluffs indifferent. But villain bluffs have real equity → actual fold% LOWER."},{q:"How much defend vs check-raise?",o:["~25%","Most of range (65–80%+)","Exactly MDF","50%"],a:1,why:"Focus on identifying the small folding range (worst hands)."},{q:"K55 two-tone. How do you organize?",o:["Around the 5","Around the king (unpaired)","Fold everything","Call everything"],a:1,why:"Can't use paired card for overcard logic. Organize around unpaired card. Ace + BDFD = pure call."},{q:"T9o on K55 two-tone, ~4.5bb raise. Action?",o:["Pure call","Pure fold (close, −0.06bb)","Check-raise","Mix"],a:1,why:"MDF ~43%, actual ~34%. T9 pure fold. QJ with ♦ = pure call; 76s = mix."},{q:"Defend priority for trash?",o:["BDFD first","1) Direct equity (A-high). 2) BDFD. 3) 3-straight. 4) BD straight. 5) Blockers.","Kicker first","None — fold all"],a:1,why:"Overcards to top pair first (ace-high), then BDFD (high card of suit), then 3-straight."}],
  s8: [{q:"IP vs OOP sizing?",o:["IP bets smaller","IP bets LARGER (can polarize, check uncaps)","Same","IP always overbets"],a:1,why:"IP checks → range uncaps on turn. OOP checks → IP punishes. IP polarizes more → bets larger."},{q:"Villain capped (low nut ratio). IP sizing?",o:["Small — get called","Overbet / pot (geometric to get stacks in)","Check","30% pot"],a:1,why:"Bigger bets vs capped ranges: fold% rises slower than bet size → more profit."},{q:"Betting < 50% pot IP is...",o:["Standard","Almost NEVER correct","Required for thin value","Only for bluffs"],a:1,why:"Small bets don't justify the risk of being check-raised off equity."},{q:"You checked turn. Villain checks river. Your pair is likely...",o:["Behind — check","Best — bet big, not small","A bluff","Irrelevant"],a:1,why:"Villain's check after your turn check-back = weakness. Your pair beats almost everything."},{q:"K-K-x → K river (quads possible). You have J-10.?",o:["Bet pot for value","Check — J-x splits all jacks, loses to K-x/quads","Bet small","Check-raise"],a:1,why:"J-x can't value bet. Would bet Queens (merge) to ~¾ pot. Quarter-pot never chosen."}],
  s9: [{q:"Bottom pair + BDFD vs c-bet?",o:["Fold — too weak","Call — BDFD > good kicker almost always","Check-raise","Fold vs any size"],a:1,why:"BDFD makes weak pairs playable. BDFD is more relevant than kicker."},{q:"Super gut shot (gut shot + BDFD)?",o:["Fold","Call — turns combo draws on suit cards","Check-raise always","Mix"],a:1,why:"Gut shot + BDFD handles heat well. Turns into combo draw on suit cards."},{q:"Naked gut shot (double unders, no BDFD)?",o:["Call — gut shot is valuable","Fold — no direct equity vs value range","Check-raise","Mix"],a:1,why:"Without BDFD or overcard, naked gut shots lack equity. Fold."},{q:"Three inputs for wide defending?",o:["Strong range + tight opponent + large bet","Weak own range + weak opponent range + small bet","Deep + passive + small bet","Short + aggressive + large bet"],a:1,why:"When both ranges are weak and the bet is small, defend very wide."},{q:"Bet sizing sensitivity?",o:["Larger bets → defend more","Larger bets → fold more pairs. Q-J without ♦: call vs 30% → fold vs 83%","No effect","Only affects bluffs"],a:1,why:"As bets scale up, fold more pairs. BDFDs and draws survive longer than naked pairs."}],
  s10: [{q:"Central thesis of river value betting?",o:["Absolute strength determines value","Relative strength (vs opponent's range) determines value","Bet only the nuts","Always check strong hands"],a:1,why:"Absolute strength irrelevant. When villain's range weakens, medium hands become relative nuts."},{q:"Villain checked turn, no raising. Your medium hand?",o:["Check — let them bet","Block bet small (25–33%) — forces them to defend 75%+","Check-raise","Fold"],a:1,why:"Lack of raising = villain range weak. Your medium hand likely best. Bet small to extract."},{q:"What does checking do to strong hands?",o:["Preserves value","Converts them to bluff catchers — IP auto-polarizes","Improves them","No effect"],a:1,why:"IP bets hands that beat you and checks hands you beat. You lose value."},{q:"Short SPR (<2x pot) with strong hand?",o:["Check — let them bluff","Prefer jamming — checking loses optionality","Check-raise","Small bet"],a:1,why:"Short SPR: jamming gets value now. Checking loses the optionality of getting stacks in."},{q:"AK on K4x → 2♠ (4-straight). BB checked to you?",o:["Check — scary card","Jam (pure) — checking costs ~270bb/100","Small bet","Check-raise"],a:1,why:"Pure jam. Opponent must call ~45% of range. Checking is a massive EV loss."}],
  s11: [{q:"Three keys to hero calling?",o:["1) Pot odds 2) Hand strength 3) Position","1) Range awareness 2) Unblock bluffs 3) Block value","1) MDF 2) Blockers 3) Sizing","1) Strength 2) Pot odds 3) Bluff freq"],a:1,why:"Know your combos, don't block opponent's bluffs, block their value."},{q:"Good vs bad bluff catcher (vs BTN opener)?",o:["Good: 8-x (blocks bluffs). Bad: 4-x.","Good: 4-x/3-x (unblocks bluffs). Bad: 8-x/9-x (blocks bluffs).","Both equal","Good: any pair. Bad: ace-high."],a:1,why:"BTN opens suited 5+ and offsuit 8+. 4-x/3-x unblock bluffs. 8-x/9-x block bluffs."},{q:"When to focus on block value vs unblock bluffs?",o:["Always block value","Wide value → unblock bluffs. Narrow → block value.","Always unblock bluffs","Never focus on blockers"],a:1,why:"Wide = hard to block specific hands → focus on not blocking bluffs. Narrow = block specific value."},{q:"No natural bluffs available?",o:["Call — MDF says so","Fold even if MDF says call","Check-raise","Call — must be bluffing"],a:1,why:"If you can't identify where bluffs come from, MDF is irrelevant. Fold."},{q:"Toy game: 22237, SPR 1x. 88 vs 87s vs pot jam?",o:["Both worth 0","88 = worth 0; 87s = ~27% pot (blocks 77, unblocks JTs)","Both same","87s worse"],a:1,why:"Not all bluff catchers equal. 87s blocks value (77) and unblocks bluffs (JTs). 88 blocks nothing useful."}],
  s12: [{q:"Two board buckets for defending 3-bets OOP?",o:["T-high+ → tight (fold 50%+); 9-high & below → resilient (~25%)","All same","Always fold","Always call"],a:0,why:"3-bettor ahead preflop. High → fold 50%+. Low → defend near MDF."},{q:"A-high or K-high boards vs 3-bet c-bet?",o:["Defend wide","Extreme caution — highest fold %, most over-defended","Call any pair","Check-raise"],a:1,why:"A/K-high most favor the 3-bettor's linear range. Fold 77/88/99, BDFDs — all folds."},{q:"K72 rainbow, AJs vs 20% c-bet?",o:["Call — ace high","Pure fold (worth 0). A-T with BDFD also = 0","Check-raise","Mix"],a:1,why:"K-high vs 3-bettor. AJs has no pair, no draw, blocks nothing. Pure fold."},{q:"984, 55 vs 33% c-bet?",o:["Fold — medium pair","Pure call (worth 100+ bb/100). Also defend AQo, KQs with BDFD.","Mix","Fold — too weak"],a:1,why:"Low board favors caller. 55 is a pair vs a board the 3-bettor misses. Pure call."},{q:"963 two-tone, 44♣ vs jam?",o:["Fold — too risky","Call — neither range hits board","Check-raise","Fold — disconnected"],a:1,why:"Low disconnected board: neither 3-bettor nor caller hits. 44 is a pair. Pure call."}],
  // ---- Bubble Mastery ----
  bmprimer: [{q:"4.5bb UTG on bubble, post BB next, fold equity now. ICM says 18%. FGS?",o:["Shove tighter — preserve stack","Shove wider (~25%) — blind cost + fold equity","Min-raise","Limp"],a:1,why:"Posting BB+ante next hand (~112bb/100) + fold equity now → FGS widens."},{q:"1.5bb UTG, forced all-in next. ICM says 49%. FGS?",o:["Shove wider — desperate","Shove tighter (~25%) — no fold equity, fold and let others bust","Same as ICM","Min-raise"],a:1,why:"No fold equity; doubling leaves same spot. Folding has value — others may bust."},{q:"15bb HJ, shorter stack present, AJo. Action?",o:["Open shove — standard","Min-raise — shoving loses ~$18 in equity","Fold","Limp"],a:1,why:"FGS eliminates open shoves for 15bb with shorter stack. Min-raise 4-5x better."},{q:"Which hand opens MORE in ICM than ChipEV?",o:["76s","T9s","A2s","55"],a:2,why:"Blockers gain value — A2s blocks Ace-X 3-bet bluffs. Speculative hands lose value."},{q:"BTN 40bb, 98o = 0.00bb in ICM sim. Blinds overfold. Action?",o:["Fold — zero EV","Open — overfolders make zero-EV hands positive","Open shove","Limp"],a:1,why:"Zero-EV assumes Nash. Overfolding opponents make fringe opens positive."},{q:"1000-player vs 200-player bubble — which more extreme?",o:["200 — fewer left","1000 — 2/152 bust rate applies more pressure","Equivalent","200 — more top-heavy"],a:1,why:"2/152 = 1.3% vs 3/33 = 9.1%. 1000-player applies more pressure per player."}],
  bm1: [{q:"Why do blockers beat playability in ICM opens?",o:["Opponents cold call wide","Opponents 3-bet/fold, not cold call","Blockers always win","Playability doesn't matter"],a:1,why:"A2s blocks 3-bet bluffs; 76s has no blocking value. Opponents 3-bet/fold in ICM."},{q:"3-bet bluff range shift ChipEV → ICM?",o:["Suited connectors → blocker-heavy (Ace-X suited, King-X suited)","Same","Blockers → suited connectors","Nothing"],a:0,why:"Board-coverage hands lose value; blocker-heavy hands gain it."},{q:"3-bet value threshold under ICM?",o:["AK, QQ, JJ all mix","Kings+ default; Queens flat; AKo barely 3-bets","Any pair","Looser than ChipEV"],a:1,why:"Value threshold tightens under ICM risk premium."},{q:"BTN open sizing ICM vs ChipEV?",o:["2.3x both","2.1x ICM vs 2.3x ChipEV — smaller yet defense tighter","2.3x ICM","Same"],a:1,why:"Smaller open in ICM, but risk premium overwhelms price — defense still tighter."},{q:"Cold calling as stacks shorten under ICM?",o:["Stays wide","Fades aggressively — calling 2bb off 20bb too risky %","Widens","No change"],a:1,why:"Calling a large % of stack near the bubble is too risky."},{q:"FGS makes 1.5bb UTG shove tighter. Why?",o:["No fold equity; folding lets others bust for you","Stack too small","ICM is wrong","Blinds too high"],a:0,why:"Doubling to 3.5bb is same spot. Folding has real value when others can bust."}],
  bm2: [{q:"You cover table from UTG at 100bb, table 20-50bb. How wide?",o:["~16.5% (baseline)","~9% (covered-tight)","~35% (~2x+ baseline)","~50%"],a:2,why:"Covering by 2x+ expands UTG to ~35%, like a 30bb CO open in chips."},{q:"BTN 80bb, BB 73bb (close). How wide?",o:["~75% (max)","~68% — closer stacks dial back","~35%","~50%"],a:1,why:"Closer stacks hurt more if you lose (7bb left) → dial back from ~75%."},{q:"BTN 12bb, BB 53bb (covered by heaps), A8o. Action?",o:["Open shove — standard 12bb jam","Fold — offsuit Ax shove terribly when covered","Min-raise","Limp"],a:1,why:"Covered by heaps; offsuit Ax are very poor; ~20% range. Common leak: autopilot shoving."},{q:"UTG 29bb, covered by most, 99. Action?",o:["Always open — nines too strong","Fold — even nines fold in some configs (~9% open)","Open shove","Limp-call"],a:1,why:"Covered and short, EP ranges get extremely tight. Nines, AJo, KQo can fold."},{q:"BTN 12bb — BB 53bb vs BB 16bb. Which wider?",o:["53bb — deeper BB = more fold equity","16bb — closer stacks = game of chicken, BB risks life","Same","Neither"],a:1,why:"BB's depth drives your range. Closer BB → wider (~28% vs ~20%)."},{q:"BB sub-5bb, you cover. Composition shift?",o:["Low suited connectors + low pairs","High-card dense, Ax-heavy — raw equity","Same","Only premiums"],a:1,why:"Very short BB → drop speculative hands, want raw equity. Reverse of deep-BB composition."}],
  bm3: [{q:"SB 11bb, BB 12bb on bubble. SB strategy?",o:["Limp most, raise premiums","Shove/raise, no limps","Min-raise all, fold to jams","Limp-fold"],a:1,why:"BB overfolds ~85%. Limping gives free equity to hands that fold to a shove."},{q:"SB covered, 10bb vs 45bb. Strategy?",o:["Limp wide","No limps; tight shove/fold (~33% VPID)","Min-raise all","Limp-shove"],a:1,why:"Below ~18bb covered, no limps. FGS: folding has value (others may bust)."},{q:"Open-shove selection when covered in ICM?",o:["Wider, weaker hands","Shift up — drop A2s/A3s, AJo threshold","Same as chip","Only premiums"],a:1,why:"Bluffs shift up with value. A2s/A3s drop; AJo becomes threshold."},{q:"SB 14bb vs BB 16bb (close). VPID vs BB 45bb?",o:["Tighter — closer stacks risk more","Wider — game of chicken, BB can't defend wide","Same","Always fold"],a:1,why:"Losing hurts BB's equity more when close → BB defends tighter → SB wider."},{q:"40+bb covered SB — limp-shove pairs?",o:["Yes, standard","Disappears — limp-call; BB can't pile vs uncapped traps","More limp-shoves","Never limp"],a:1,why:"SB is uncapped with traps; BB can't pile. Limp-call instead."},{q:"BB fold freq vs SB cover (short) vs chip model?",o:["~37% both","~78-90% (ICM) vs ~37% (chip)","~50%","Same"],a:1,why:"ICM pressure doubles BB fold frequency vs chip model."}],
  bm4: [{q:"SB 11bb covers BB on bubble. Limp or shove?",o:["Limp — see cheap flop","Shove/raise — BB overfolds ~85%, limping gives free equity","Min-raise all","Limp-fold"],a:1,why:"BB overfolds ~85%. Limping gives free equity realization to hands that'd fold to shove."},{q:"Limping reappears for covered SB at what depth?",o:["10bb","18bb","25bb","30bb"],a:1,why:"~18bb effective — deep enough that BB can't easily leverage against a limp."},{q:"SB 14bb vs BB 16bb. VPID vs BB 45bb?",o:["Tighter","Wider — game of chicken, BB can't defend wide","Same","Always fold"],a:1,why:"Close stacks: losing hurts BB more → BB defends tighter → SB wider."},{q:"Covered SB 37+bb. Limp-shove pairs?",o:["Yes","Disappears — limp-call; BB can't pile vs uncapped traps","More","Never limp"],a:1,why:"SB uncapped with traps at depth; BB can't pile. Limp-call instead."},{q:"Covering SB at 22bb — shove or limp?",o:["Always shove","Depends on other-table ICM pressure","Always limp","Fold"],a:1,why:"More other-table pressure = more shoving; less = more limping."},{q:"BB fold freq vs SB cover (short) vs chip model?",o:["~37% both","~78-90% (ICM) vs ~37% (chip)","~50%","Same"],a:1,why:"ICM pressure roughly doubles BB fold frequency."}],
  bm5: [{q:"SB 17bb facing BTN open, covered. Cold-call freq?",o:["~15% — suited connectors","~0% — raise/fold only","~25%","~5%"],a:1,why:"Below ~20bb, SB has ~0% cold-call range. Raise/fold only."},{q:"BB 14bb, covered, BTN opens wide, A5s. Action?",o:["Call — suited, playable","Re-steal shove — win outright, avoid postflop losses","Fold","Min-3-bet"],a:1,why:"Re-steal wins outright more often; Ax blocker powerful. Calling loses ~50%+ postflop."},{q:"BB 45bb covers UTG 15bb (3x). Defense width?",o:["Very tight — premiums only","Call everything suited, fold dominated offsuit","3-bet bluff any two","Limp behind"],a:1,why:"Cover by heaps → defend wide but trim dominated offsuit. King-X offsuit ~0 EV."},{q:"3-bet sizing in high ICM from blinds?",o:["Smaller than chip","Size up — deny equity, lower SPR for narrow value","Same","Min-raise"],a:1,why:"Larger 3-bets deny equity to speculative calls and lower SPR."},{q:"3-bet value threshold covered vs EP?",o:["AK, QQ, JJ","Kings+, AQ (Queens mix)","Any pair","Looser"],a:1,why:"Much narrower than chip model under ICM risk premium."},{q:"SB cold calls wider when BB is short — why?",o:["BB overcalls","BB handcuffed — can't squeeze/lead; SB 'almost in the BB'","SB has fold equity","No reason"],a:1,why:"BTN opens 70%+; BB can't squeeze or lead post → SB realizes more equity."}],
  bm6: [{q:"UTG 50bb, BTN 51bb 3-bets. Your defense?",o:["Pure raise/fold — no cold calls","Mix of cold calls and 4-bets — you cover the 3-bettor","Fold all but Aces","Shove all pairs"],a:1,why:"Cover the 3-bettor (50v51 'chicken') → cold call ~24%. Covered (25v50) → raise/fold."},{q:"CO 32bb covers UTG 17bb, BB short. Cold call width?",o:["Very tight — UTG too strong","Wider than chips — you cover and BB is short (protected)","No cold calls","Only pairs"],a:1,why:"Covering + short BB = protected. 54s, 65s, A4s become calls."},{q:"Raise to 7.9bb leaving 0.1 behind. Better?",o:["Standard — 0.1 doesn't matter","Raise to ~5bb — fold to jam+call behind (caller shows QQ+)","Shove always","Min-raise"],a:1,why:"Leaving 0.1bb is a leak. Raise to ~5bb allows a fold to jam+call behind."},{q:"SB 17bb vs UTG open, BB 10bb. Cold-call range?",o:["None — always raise/fold","Narrow value range — protected (UTG tight, BB can't squeeze)","Call everything suited","Only Ax"],a:1,why:"UTG's tight range + short BB = SB protected. Cold call KQs, A9s, mid pairs."},{q:"3-bet sizing at 45+bb deep in ICM?",o:["~5bb","~8-8.5bb","Min-raise","~3bb"],a:1,why:"Size up at depth: ~8-8.5bb. But matching range to size matters more than number."},{q:"Over-exploiting on the bubble is doubly costly because?",o:["Opponents adjust faster","Stolen equity spreads to ALL players, not just exploiter","Solvers can't model it","It's not"],a:1,why:"In ICM, equity stolen from you spreads to all players — over-exploitation is doubly costly."}],
  bm7: [{q:"14-pay, 16 left, 2 to bust. UTG 25bb, 4bb stack other table with full orbit before BB. vs default?",o:["Much wider","Slightly wider — 2/16 lower pressure + full orbit","Tighter","Same"],a:1,why:"2 to bust / 16 = lower %; threatened stack has full orbit. Both push looser."},{q:"BTN 50bb, BB 20bb, A♣Q♦5♠, A9. Facing c-bet?",o:["Check-raise all-in","Check-call — ace-high lockdown, no protection needed","Donk-lead","Check-fold"],a:1,why:"Top pair ~88-90% on A-K-x/A-Q-x; board locked down → pure check-call."},{q:"Q♥8♣3♦, KQ. BTN c-bets. Action?",o:["Check-call","Check-raise all-in — ~85% eq, K/A turn can outdraw","Donk-lead","Check-fold"],a:1,why:"Q/J-high top pair ≥83-85% gets check-raised; outdraw cards exist. Ace-high same equity doesn't."},{q:"BTN 50bb covers BB 20bb. Flop 8♥5♦3♣. C-bet?",o:["Check ~33% like chip","Range bet — BB too tight to connect, rarely check-raises","Check all","Bet value only"],a:1,why:"Low boards become range-bets when covering: BB defense too tight, XR ~11%."},{q:"A♣K♣8♦ (monotone). BTN covering. Strategy?",o:["Range bet — all A-side monotone","Check back some — connects OOP's flatting range (K-8, A-8)","Check ~60%","Bet flush draws only"],a:1,why:"A-K-8♣ connects with OOP — distinguish from A-5-2♣ which BTN range-bets."},{q:"K♣K♦9♥. BTN covering. C-bet?",o:["Range bet","Check back some — 9 connects BB (unlike K-K-4)","Check all","Bet kings only"],a:1,why:"K-K-9/K-K-8 get check-back (mid card gives BB pairs). K-K-4 ~95% range bet."}],
  bm8: [{q:"Covered BB on bubble — donk lead freq?",o:["Often — take initiative","Almost never — BTN's wider range connects better","~50%","Always"],a:1,why:"Leads are very muted; BTN connects better, BB's tight range connects worse."},{q:"BB check-raise sizing on low boards under ICM?",o:["Small raise","All-in (check-shove) — maximize protection","Check-call","Min-raise"],a:1,why:"Small raises let IP draw out — catastrophic under ICM. Shove to deny equity."},{q:"A-A-8 vs A-8-8 as covered BB — which gets check-raise range?",o:["A-A-8","A-8-8 — BB has the pair","Both","Neither"],a:1,why:"High-low-low (A-8-8): BB has 8x → raise. High-high-low (A-A-8): no pair → check-call."},{q:"Turn FD on board — check-call or raise with made hand?",o:["Always call","Call if unblock IP's bluffs; raise if block them","Always raise","Fold"],a:1,why:"Unblock bluffs → call (face bluffs you beat). Block bluffs → raise (face value you stack)."},{q:"BTN covers BB — default c-bet strategy?",o:["Check more like chip","Range bet — BB rarely check-raises, BTN has coverage","Bet value only","Check all"],a:1,why:"BB XR far less; BTN ~70% vs BB ~20-30% defense. Risk factors neutralized."},{q:"When is 'always range-bet' approximately correct?",o:["Always","When you cover BB by more than ~2x their stack","Never","Only ace-high"],a:1,why:"Covering by 2x+ → BB can't fight back → range-bet almost all boards."}],
  bm9: [{q:"BB covers BTN 2:1, flop 5♠5♥4♦. BB checks. You're BTN.",o:["Range c-bet small","Check back near-range — stacks reversed, actions reversed","C-bet 75%","Check only air"],a:1,why:"BB has the low cards and leads near-range when covering. If BB checks (under-leads), check back range."},{q:"BTN covered, A♣Q♠2♦ rainbow, A♦J♦. Best line?",o:["Small c-bet 33%","Check back","Overbet ~105% — fold out gutters","Check-raise"],a:2,why:"A-Q-2 with no open-ender/no FD = front-load overbet: fold out 5-4/4-3, clean turns."},{q:"Same A♣Q♠2♦ but two-tone with FD. What changes?",o:["Overbet bigger","Overbet off — don't want bet-call vs drawing stacks-in","Switch to range-bet","Check range"],a:1,why:"Flush draw kills the front-load. Revert to small/check."},{q:"J♣J♦2♠, BB covers 2:1, BTN c-bets, 99. Action?",o:["Check-call","Check-raise — heavy CR board when covering","Donk-jam","Check-fold"],a:1,why:"J-J-2 is check-raise-heavy when covering. Check-calls appear more on J-J-9 two-tone."},{q:"Covered BTN, J♠9♠ flush, river 25% block, want to raise. Sizing?",o:["Jam all-in","Raise to ~50% of remaining, non-all-in","Min-raise","Just call"],a:1,why:"River polar → raise non-all-in to preserve tournament equity. Never jam when avoidable."},{q:"Covered BTN, 9♠6♥3♦ rainbow, T♦T♣. BB checks. Action?",o:["Check back","Small c-bet, fold to raise","Jam ~118% — protection > induction","C-bet 75%, call jam"],a:2,why:"Jam tens to deny draws; bet-calling lets BB check-raise draws and stack you."}],
  bm10: [{q:"BB 17bb covered by UTG 31bb, K♣J♦ on K♠8♣4♥. Action?",o:["Check-raise for value","Check-call — ICM threshold is KQ only","Check-shove","Check-fold"],a:1,why:"ICM check-raise threshold: KQ+. KJ and below pure check-call. Check-shove needs >75% fold, UTG folds ~60%."},{q:"BB 17bb, nuts on river, polar sizing?",o:["Shove all-in","~13.5bb leaving 1-3bb behind — never shove","40% pot","Check-raise"],a:1,why:"1-3bb worth ~$200 in $100 tourney. Shoving when called+lose = zero equity."},{q:"9♦4♠4♣, BB 17bb covered. Strategy?",o:["Check-raise aggressively","Mostly check-call — tight range lacks 9x/4x coverage","Check-shove","Donk bet"],a:1,why:"Range composition overrides board texture. At 17bb, BB barely has 9x/4x."},{q:"Q♣J♦2♠ → A♠ turn, BB 17bb, A♥J♠. Lead freq?",o:["Rarely — flushes rare","~40% — flushes 17.8% of tight suited-heavy range","Always","Never"],a:1,why:"Tight range is suited-heavy → 17.8% flushes on A♠ (vs 12.5% deep). Leads 40% on A♠, 26% on 4♠."},{q:"UTG 29bb covers BB 17bb, 9♠7♥7♦. C-bet?",o:["Check — 977 connects BB","Range bet — BB's tight defense lacks 7x; cover by 2x+","Check 50%","Bet small polar"],a:1,why:"BB defense at 17bb doesn't even call 7x suited. ICM pressure lets you range-bet."},{q:"UTG 66bb vs BB 58bb (close), 7♠6♦4♣. C-bet?",o:["Range bet — you cover","~50% check — close stacks = game of chicken","Check all","Overbet"],a:1,why:"Stack gap > coverage. Close stacks → check ~50% on mid connected. BB may lead."}],
  bm11: [{q:"BTN 12bb polar, BB 16bb, K♠5♠4♥ (two-tone). vs K5-4 rainbow?",o:["Range bet — same as rainbow","Check slightly more + add flop jams","Check less","Pure check"],a:1,why:"Two-tone increases checking (~57%) and introduces flop jams to stop check-shoves with bare FDs."},{q:"BTN 12bb vs BB 53bb, J♣5♦4♠ (dry). BB checks. BTN?",o:["Check ~50% (same as 16bb)","Range bet — tighter range = more value, less air","Pure check","Small bet sets only"],a:1,why:"Tighter preflop range has more top pair/overpair/set, less air → range-bet dry board."},{q:"Flop A♥9♥9♦ (two-tone, paired), 12bb vs 16bb. Key risk?",o:["BTN has too much air","BB has 9x coverage + will check-raise; BTN lacks 9x","Range-bet — BTN has aces","Jam any ace"],a:1,why:"Mid-pair boards with draws invite BB aggression; BTN lacks 9x → check back, don't over-c-bet."},{q:"6♦6♠2♣ (rainbow, low paired, dry), 12bb vs 16bb. Strategy?",o:["Check back — BB has trips","Range bet — BB underrepresented on the deuce","67% check","Small bet only"],a:1,why:"BB has few 6x/2x, underrepresented. Range bet. Contrast 6-6-5 (draws) which checks ~40%."},{q:"Q♠7♥4♦ (monotone), BB under-leads (<20%). Exploit?",o:["Range bet to deny flush equity","Check back range — no betting range needed","Jam all air","Small bet FDs"],a:1,why:"If BB under-leads monotone, BTN checks back range. Monotone heavily checked in ICM regardless."},{q:"BTN 12bb vs 53bb BB. Preflop adjustment vs 16bb?",o:["Open wider — BB has more chips","Open tighter; BB defends wider","Same range","Open tighter; BB defends tighter"],a:1,why:"Every tier shifts up (tighter), but deep BB has less ICM risk → defends wider, 3-bets blocker-heavy."}],
};
